// Period mode: quiet early-Renaissance consort music (c. 1500) generated by
// rule. Instruments are small physical caricatures: a plucked lute, a recorder
// with breath, a bowed viol (saw through body resonances with bow noise) and a
// shawm. Phrases are modal random walks with cadences and rests, so nothing
// loops audibly. Every musical generator calls markMusic(); the offline test
// uses the counter to prove 'nature' mode never instantiates music.

import { Voice, tone, burst, pluck, vowelNote, filter, gainNode, mtof, envelope } from './dsp.js';
import { BUTTOCK_SONG } from './buttockSong.js';

export const musicStats = { instantiated: 0 };
export function markMusic() { musicStats.instantiated++; }

const MODES = {
  dorian: [0, 2, 3, 5, 7, 9, 10],
  mixolydian: [0, 2, 4, 5, 7, 9, 10],
  phrygian: [0, 1, 3, 5, 7, 8, 10],
  lydian: [0, 2, 4, 6, 7, 9, 11],
  aeolian: [0, 2, 3, 5, 7, 8, 10],
};

// scale degree (0 = final, may be negative or > 6) -> midi
export function degToMidi(final, mode, deg) {
  const sc = MODES[mode];
  const oct = Math.floor(deg / 7);
  return final + 12 * oct + sc[((deg % 7) + 7) % 7];
}

// --- instruments ------------------------------------------------------------

export function lute(ctx, dest, o) {
  pluck(ctx, dest, { t0: o.t0, f: o.f, gain: o.gain, dur: o.dur ?? 1.6, bright: o.bright ?? 6 });
  // a second course slightly out of tune gives the double-string shimmer
  pluck(ctx, dest, { t0: o.t0 + 0.006, f: o.f, gain: o.gain * 0.45, dur: (o.dur ?? 1.6) * 0.8, bright: 5, detune: 6 });
}

export function recorder(ctx, dest, rng, o) {
  const { t0, f, dur, gain } = o;
  // tone with a short upward scoop at the onset and a little vibrato
  tone(ctx, dest, { t0, dur, f: f * 0.985, f1: f, glide: 0.05, type: 'triangle', gain, a: 0.035, r: Math.min(0.08, dur * 0.3), vib: { rate: 5.2, depth: 6 }, filter: { type: 'lowpass', f: 3200 } });
  tone(ctx, dest, { t0, dur, f: f * 2, type: 'sine', gain: gain * 0.18, a: 0.04, r: Math.min(0.08, dur * 0.3) });
  // breath: a chiff at the attack and a soft air stream under the note
  burst(ctx, dest, rng, { t0, dur: Math.min(0.12, dur), kind: 'pink', a: 0.008, r: 0.06, gain: gain * 0.5, filter: { type: 'bandpass', f: f * 2.5, Q: 2 } });
  burst(ctx, dest, rng, { t0, dur, kind: 'pink', a: 0.05, r: Math.min(0.1, dur * 0.3), gain: gain * 0.14, filter: { type: 'bandpass', f: 2800, Q: 0.8 } });
}

export function viol(ctx, dest, rng, o) {
  const { t0, f, dur, gain } = o;
  const a = Math.min(0.28, dur * 0.35), r = Math.min(0.25, dur * 0.3);
  const env = ctx.createGain();
  envelope(env.gain, t0, gain, a, dur, r);
  env.connect(dest);
  // body: two resonances plus a dull direct path
  const body1 = filter(ctx, 'bandpass', 230, 3.5), body2 = filter(ctx, 'bandpass', 540, 2.5), direct = filter(ctx, 'lowpass', 1800, 0.7);
  const b1g = gainNode(ctx, 0.9), b2g = gainNode(ctx, 0.6), dg = gainNode(ctx, 0.35);
  body1.connect(b1g).connect(env); body2.connect(b2g).connect(env); direct.connect(dg).connect(env);
  for (const d of [-4, 4]) {
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.value = f;
    osc.detune.value = d;
    const v = ctx.createOscillator();
    v.frequency.value = 5.4 + rng.range(-0.3, 0.3);
    const vg = gainNode(ctx, 9);
    v.connect(vg).connect(osc.detune);
    v.start(t0); v.stop(t0 + dur + 0.05);
    osc.connect(body1); osc.connect(body2); osc.connect(direct);
    osc.start(t0); osc.stop(t0 + dur + 0.05);
  }
  // bow hair noise, strongest during the attack
  burst(ctx, env, rng, { t0, dur, kind: 'pink', a: 0.02, r: r, gain: 0.25, filter: { type: 'highpass', f: 2200, Q: 0.7 } });
}

export function shawm(ctx, dest, o) {
  const { t0, f, dur, gain } = o;
  tone(ctx, dest, { t0, dur, f: f * 0.99, f1: f, glide: 0.08, type: 'sawtooth', gain, a: 0.06, r: Math.min(0.12, dur * 0.3), filter: { type: 'bandpass', f: 1250, Q: 2.2 }, vib: { rate: 4.8, depth: 7 } });
  tone(ctx, dest, { t0, dur, f, type: 'sawtooth', gain: gain * 0.5, a: 0.06, r: Math.min(0.12, dur * 0.3), filter: { type: 'bandpass', f: 2600, Q: 3 } });
}

// --- phrase engine ------------------------------------------------------------

/**
 * Registers a melodic line on a Voice: modal random walk in phrases that end
 * with a cadence (approach from above or below onto the final or fifth),
 * separated by rests. play(t, midi, beatsDur) performs one note.
 */
export function melodyLine(v, cfg, play) {
  const { final, mode, tempo, rhythms, lo, hi, phraseMin = 5, phraseMax = 9, restMin = 1, restMax = 4, leapChance = 0.15, delay = 0 } = cfg;
  const beat = 60 / tempo;
  const rng = v.rng;
  let deg = rng.int(0, 4), left = 0, cadence = 0;
  v.pattern(delay, (t) => {
    if (left <= 0 && cadence <= 0) {
      left = rng.int(phraseMin, phraseMax);
      cadence = 2;
      return beat * rng.range(restMin, restMax);
    }
    let next;
    if (left > 0) {
      left--;
      const step = rng.chance(leapChance) ? rng.pick([-4, -3, 3, 4]) : rng.pick([-2, -1, -1, 0, 1, 1, 2]);
      next = deg + step;
      if (next < lo) next = lo + rng.int(0, 2);
      if (next > hi) next = hi - rng.int(0, 2);
    } else {
      // cadence: penultimate note a step away from the goal, then the goal
      const goal = rng.chance(0.7) ? 0 : 4;
      next = cadence === 2 ? goal + rng.pick([-1, 1, 1]) : goal;
      cadence--;
    }
    deg = next;
    const beats = cadence === 0 && left === 0 ? rng.pick([2, 3, 4]) : rng.pick(rhythms);
    play(t, degToMidi(final, mode, deg), beats * beat, beats);
    return beats * beat;
  });
}

// chord roots used for the lute, as scale degrees
const PROGRESSIONS = [[0, 4, 3, 0], [0, 6, 3, 4], [0, 2, 4, 0], [3, 0, 4, 0]];

// --- consorts, one per panel -------------------------------------------------

function edenConsort(ctx, seed) {
  markMusic();
  const v = new Voice(ctx, seed);
  const tempo = 54, beat = 60 / tempo, final = 62, mode = 'dorian';
  const room = filter(ctx, 'lowpass', 4000, 0.7);
  room.connect(v.out);
  // recorder: slow, stepwise, long rests
  melodyLine(v, { final, mode, tempo, rhythms: [1, 1, 2, 2, 3], lo: 0, hi: 9, phraseMin: 4, phraseMax: 7, restMin: 2, restMax: 6, leapChance: 0.08, delay: 1.5 },
    (t, midi, dur) => recorder(ctx, room, v.rng, { t0: t, f: mtof(midi + 12), dur: dur * 0.9, gain: 0.05 }));
  // viol tenor: long notes drawn from the chord
  let prog = v.rng.pick(PROGRESSIONS), bar = 0;
  v.pattern(0.3, (t) => {
    const root = prog[bar % prog.length];
    bar++;
    if (bar % prog.length === 0) prog = v.rng.pick(PROGRESSIONS);
    const beats = 4;
    if (v.rng.chance(0.85)) viol(ctx, room, v.rng, { t0: t + v.rng.range(0, 0.04), f: mtof(degToMidi(final, mode, root) - 12), dur: beats * beat * 0.95, gain: 0.05 });
    // lute: a gentle arpeggiated chord on the bar, sometimes again on beat 3
    const chord = [root, root + 2, root + 4, root + 7].map((d) => mtof(degToMidi(final, mode, d)));
    const strum = (tt, g) => chord.forEach((f, i) => lute(ctx, room, { t0: tt + i * 0.035, f, gain: g * (1 - i * 0.12), dur: 2.2 }));
    strum(t, 0.045);
    if (v.rng.chance(0.5)) strum(t + 2 * beat, 0.03);
    return beats * beat;
  });
  return v;
}

function gardenConsort(ctx, seed) {
  markMusic();
  const v = new Voice(ctx, seed);
  const tempo = 116, beat = 60 / tempo, final = 67, mode = 'mixolydian';
  const room = filter(ctx, 'lowpass', 5000, 0.7);
  room.connect(v.out);
  // recorder melody with a saltarello lilt (long-short in 6/8)
  melodyLine(v, { final, mode, tempo, rhythms: [1, 1, 0.5, 0.5, 1.5, 1, 2], lo: 0, hi: 10, phraseMin: 6, phraseMax: 12, restMin: 1.5, restMax: 5, leapChance: 0.22, delay: 0.8 },
    (t, midi, dur) => recorder(ctx, room, v.rng, { t0: t, f: mtof(midi + 12), dur: dur * 0.85, gain: 0.045 }));
  // lute: strummed dance rhythm, dropping out for a bar now and then
  let prog = v.rng.pick(PROGRESSIONS), bar = 0, resting = 0;
  v.pattern(0.1, (t) => {
    const root = prog[bar % prog.length];
    bar++;
    if (bar % prog.length === 0) { prog = v.rng.pick(PROGRESSIONS); resting = v.rng.chance(0.25) ? 1 : 0; }
    if (resting) { resting = 0; return 3 * beat; }
    const chord = [root, root + 4, root + 7, root + 9].map((d) => mtof(degToMidi(final, mode, d) - 12));
    const hits = [[0, 0.05], [1.5 * beat, 0.03], [2 * beat, 0.035]];
    for (const [off, g] of hits) chord.forEach((f, i) => lute(ctx, room, { t0: t + off + i * 0.012, f, gain: g * (1 - i * 0.1), dur: 1.2 }));
    return 3 * beat;
  });
  // viol: a light drone-less bass, one note per bar, sometimes two
  v.pattern(0.1, (t) => {
    const root = prog[(bar - 1 + prog.length) % prog.length];
    if (v.rng.chance(0.7)) viol(ctx, room, v.rng, { t0: t, f: mtof(degToMidi(final, mode, root) - 24), dur: 3 * beat * 0.8, gain: 0.035 });
    return 3 * beat;
  });
  return v;
}

function hellConsort(ctx, seed) {
  markMusic();
  const v = new Voice(ctx, seed);
  const tempo = 58, beat = 60 / tempo, final = 52, mode = 'phrygian';
  const dark = filter(ctx, 'lowpass', 2600, 0.8);
  dark.connect(v.out);
  // cantus firmus: the buttock song on the viol, slow, with a voice joining now and then
  const cf = BUTTOCK_SONG.notes;
  let i = 0, singing = false;
  v.pattern(0.5, (t) => {
    if (i >= cf.length) { i = 0; singing = v.rng.chance(0.5); return beat * v.rng.range(4, 9); }
    const n = cf[i++];
    const dur = n.beats * 2 * beat;
    if (n.midi == null) return dur;
    viol(ctx, dark, v.rng, { t0: t, f: mtof(n.midi - 12), dur: dur * 0.95, gain: 0.06 });
    if (singing) vowelNote(ctx, dark, { t0: t + 0.02, dur: dur * 0.9, f: mtof(n.midi), vowels: [['u', 0], ['o', 0.6]], gain: 0.04, a: 0.2, r: 0.3, voices: 2, detune: 6, vib: { rate: 4.4, depth: 6 } });
    return dur;
  });
  // lute: sparse low plucks on phrygian degrees
  v.pattern(1.2, (t) => {
    const d = v.rng.pick([0, 0, 1, 4, -3, 5]);
    lute(ctx, dark, { t0: t, f: mtof(degToMidi(final, mode, d) - 12), gain: 0.045, dur: 2.4, bright: 4 });
    return beat * v.rng.pick([1, 2, 2, 3, 4]);
  });
  // shawm: rare short phrygian phrases, far off
  const far = filter(ctx, 'lowpass', 1800, 0.7);
  far.connect(dark);
  melodyLine(v, { final: final + 12, mode, tempo, rhythms: [1, 1, 2], lo: 0, hi: 7, phraseMin: 3, phraseMax: 5, restMin: 8, restMax: 20, leapChance: 0.1, delay: 6 },
    (t, midi, dur) => shawm(ctx, far, { t0: t, f: mtof(midi), dur: dur * 0.9, gain: 0.03 }));
  return v;
}

export const MUSIC_BEDS = { eden: edenConsort, garden: gardenConsort, hell: hellConsort };
